/**
 * Skill input-coverage analysis.
 *
 * The platform's current skill contract keeps the form schema and lookup
 * bindings in the instructions Markdown while tool fields/inputs are
 * structured resources. This module compares those two real sources instead
 * of inventing a second persisted schema. The headings and list shape match
 * the skill generator contract:
 *
 *   ## Input Schema
 *   - field_name (required): description
 *
 *   ## Lookup Notes
 *   - field_name: resolve_field_name (source_table)
 */
export interface SkillInputDefinition {
    readonly name: string;
    readonly description?: string;
    readonly required?: boolean;
}
export interface SkillLookupDefinition {
    readonly input: string;
    readonly tool: string;
    readonly source?: string;
}
export interface DecomposedSkillInstructions {
    readonly prose: string;
    readonly inputs: readonly SkillInputDefinition[];
    readonly lookups: readonly SkillLookupDefinition[];
}
export interface SkillCoverageTool {
    readonly name: string;
    readonly fields: readonly string[];
    readonly inputs: readonly string[];
}
export type SkillCoverageTarget = {
    readonly kind: "lookup";
    readonly tool: string;
} | {
    readonly kind: "field";
    readonly tool: string;
    readonly name: string;
} | {
    readonly kind: "input";
    readonly tool: string;
    readonly name: string;
};
export interface SkillCoverageBinding {
    readonly input: string;
    readonly targets: readonly SkillCoverageTarget[];
}
export type SkillCoverageGap = {
    readonly kind: "input-schema-missing";
} | {
    readonly kind: "missing-field";
    readonly input: string;
} | {
    readonly kind: "missing-lookup-tool";
    readonly input: string;
    readonly tool: string;
} | {
    readonly kind: "unbound-lookup";
    readonly input: string;
    readonly tool: string;
} | {
    readonly kind: "leftover-tool";
    readonly tool: string;
};
export interface SkillInputCoverageReport {
    readonly skill: string;
    readonly inputs: readonly string[];
    readonly tools: readonly string[];
    readonly bindings: readonly SkillCoverageBinding[];
    readonly gaps: readonly SkillCoverageGap[];
}
export declare function parseSkillInputDefinition(line: string): SkillInputDefinition | undefined;
export declare function parseSkillLookupDefinition(line: string): SkillLookupDefinition | undefined;
export declare function formatSkillInputSchema(inputs: readonly SkillInputDefinition[]): string;
export declare function formatSkillLookupNotes(lookups: readonly SkillLookupDefinition[]): string;
export declare function deriveSkillInstructions(baseProse: string | undefined, inputs?: readonly SkillInputDefinition[], lookups?: readonly SkillLookupDefinition[]): string;
export declare function decomposeSkillInstructions(markdown: string): DecomposedSkillInstructions;
/** Compare instruction-declared form variables with the deployed tool surface. */
export declare function analyzeSkillInputCoverage(skill: string, instructions: string, coverageTools: readonly SkillCoverageTool[]): SkillInputCoverageReport;
/** Informational coverage lines emitted on stderr and in JSON `reports`. */
export declare function skillCoverageReportLines(report: SkillInputCoverageReport): string[];
/** Only actionable gaps; these remain warnings and JSON `diagnostics`. */
export declare function skillCoverageGapDiagnostics(report: SkillInputCoverageReport): string[];
/** Convert a skill def() payload's closed tool envelopes to analyzer input. */
export declare function coverageToolsFromWire(entries: readonly Record<string, unknown>[]): SkillCoverageTool[];
